import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第三十一卦 咸 泽山咸 兑上艮下","description":"周易 - 第三十一卦 咸 泽山咸 兑上艮下","frontmatter":{"title":"第三十一卦 咸 泽山咸 兑上艮下","description":"周易 - 第三十一卦 咸 泽山咸 兑上艮下"},"headers":[],"relativePath":"zh/classics/zhouyi/032.md","filePath":"zh/classics/zhouyi/032.md"}'),l={name:"zh/classics/zhouyi/032.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="咸" tabindex="-1">咸 <a class="header-anchor" href="#咸" aria-label="Permalink to “咸”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨，利贞，取女吉。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>咸，感也。柔上而刚下，二气感应以相与，止而说，男下女，是以亨利贞，取女吉也。天地感而万物化生，圣人感人心而天下和平；观其所感，而天地万物之情可见矣！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>山上有泽，咸；君子以虚受人。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>咸其拇。象曰：咸其拇，志在外也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>咸其腓，凶，居吉。象曰：虽凶，居吉，顺不害也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>咸其股，执其随，往吝。象曰：咸其股，亦不处也。志在随人，所执下也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>贞吉悔亡，憧憧往来，朋从尔思。象曰：贞吉悔亡，未感害也。憧憧往来，未光大也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>咸其脢，无悔。象曰：咸其脢，志末也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>咸其辅，颊，舌。象曰：咸其辅，颊，舌，滕口说也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
